// Types of the agent loop (spec section 13): the InvestigationResult and the pieces it is made of. Meter kWh are SAMPLE data.
import type { Decomp, HypothesisId, HypothesisResult } from "./hypotheses/types.ts";
import type { Evidence } from "./evidence.ts";
import type { Fact } from "./facts.ts";
import type { Answer, VerifyError } from "./verifier.ts";
import type { Recommendation, TariffComparison } from "./recommend.ts";
import type { Route } from "./provider_shared.ts";
import type { DateWindow } from "./windows.ts";

export const INTENT_TYPES = ["why_cost_change", "why_spike_day", "why_emissions", "what_to_change"] as const;
export type IntentType = (typeof INTENT_TYPES)[number];

export interface Intent {
  type: IntentType;
  requestedSites: string[];                   // as written by the model or the user ("Brixton", "site 2", "ALL")
  dates: string[];                            // YYYY-MM-DD
  source: "llm" | "fallback";                 // fallback: deterministic keyword rules after the model failed twice
}

export interface ExtraSql {
  purpose: string; sql: string;
  status: "ran" | "rejected" | "failed";
  reason?: string;                            // why it was rejected by the guard or failed in Zetaris
  evidence?: string; rows?: number;
}
export interface Plan {
  hypotheses: HypothesisId[];                 // in run order, including the ones the system added
  added: HypothesisId[];                      // added by code: H7-H9 data checks, and the tests the question type needs
  dropped: string[];                          // ids the model proposed that are not in the catalog
  extraSql: ExtraSql[];
  rationale: string;
  source: "llm" | "default";
}

export interface LlmCall { step: string; route?: Route; error?: string; wallMs?: number; rejected?: string }   // rejected: why the reply could not be used, with the start and end of its text   // wallMs: the whole call as the agent saw it, including a Meterless attempt that timed out before the fallback answered
export interface Timings { total: number; [step: string]: number }   // milliseconds

export interface Verification {
  passed: boolean; attempts: number; mode: "llm" | "template";
  errors: string[];                           // why the model's last attempt failed (empty when an LLM answer passed); template runs append their own check
  errorDetail: VerifyError[];
  history: { attempt: number; errors: string[]; repairs: string[] }[];   // every failed narrative attempt with its errors (what the corrections fixed)
  repairs: string[];                          // repairs code applied to the accepted answer (digits turned into placeholders, sentences dropped for status contradictions)
}

export interface ScopeInfo { label: string; sites: { id: string; name: string }[]; windowA: DateWindow; windowB: DateWindow }

/** The decomposition without the per-slot arrays (those stay in the evidence store / Zetaris). */
export type DecompositionSummary = Omit<Decomp, "windowA" | "windowB" | "aligned"> & { slotsAligned: number; slotsExpected: number };

export interface InvestigationResult {
  question: string;
  intent: Intent;
  scope: ScopeInfo;
  decomposition: DecompositionSummary;
  plan: Plan;
  results: HypothesisResult[];
  evidence: Evidence[];
  facts: Fact[];
  recommendation: { loadShift: Recommendation | null; tariff: TariffComparison | null };
  answer: Answer;
  verification: Verification;
  llmCalls: LlmCall[];
  timings: Timings;
  notes: string[];
  sampleDataNote: string;
}
export interface ClarificationResult { question: string; clarification: string; knownSites: { id: string; name: string }[]; llmCalls: LlmCall[]; timings: Timings }
export type InvestigateOutcome = InvestigationResult | ClarificationResult;
export const isClarification = (o: InvestigateOutcome): o is ClarificationResult => "clarification" in o;

export const SAMPLE_NOTE = "Meter kWh are SAMPLE data (synthetic, Crumb & Co); Agile prices (Octopus), carbon intensity (NESO) and temperatures (Open-Meteo) are real public data.";

// Progress events of an investigation, for a live UI: step started / finished (with milliseconds), evidence created, each LLM call with its route,
// each hypothesis result. `investigate(question, { onEvent })` calls the listener synchronously; a throwing listener never breaks the run.
import type { Evidence } from "./evidence.ts";
import type { LlmCall } from "./agent_types.ts";

export type StepName = "sites" | "intent" | "plan" | "data" | "hypotheses" | "recommend" | "extraSql" | "facts" | "narrative" | "template";
export type ProgressEvent =
  | { type: "step"; step: StepName; status: "started" | "finished"; ms?: number }
  | { type: "evidence"; evidence: { id: string; hypothesisId: string; title: string; rowCount: number; zetarisRunId: string; sources: Evidence["sources"] } }
  | { type: "hypothesis"; id: string; name: string; status: string }
  | { type: "llm"; call: LlmCall }
  | { type: "reset"; reason: string }   // the speculative data work was for a different scope: clear evidence and hypotheses shown so far
  | { type: "done"; totalMs: number };

export type Emit = (e: ProgressEvent) => void;

/** Wraps a listener so that it can be called without checks and cannot throw into the caller. */
export function safeEmit(listener?: (e: ProgressEvent) => void): Emit {
  return (e) => { try { listener?.(e); } catch { /* a UI listener must never break the investigation */ } };
}

/** Runs `fn` between a "started" and a "finished" event; the elapsed milliseconds are added to `timings[step]`. */
export async function timed<T>(emit: Emit, timings: Record<string, number>, step: StepName, fn: () => Promise<T>): Promise<T> {
  const s = performance.now();
  emit({ type: "step", step, status: "started" });
  try { return await fn(); } finally {
    const ms = Math.round(performance.now() - s);
    timings[step] = (timings[step] ?? 0) + ms;
    emit({ type: "step", step, status: "finished", ms });
  }
}

export const evidenceEvent = (e: Evidence): ProgressEvent => ({ type: "evidence", evidence: { id: e.id, hypothesisId: e.hypothesisId, title: e.title, rowCount: e.rowCount, zetarisRunId: e.zetarisRunId, sources: e.sources } });

// Evidence records (spec section 12): one per Zetaris query + the deterministic metrics computed from its rows.
// Ids are sequential per investigation (E1, E2, ...), the result hash is sha256 over canonical JSON (sorted keys) of ALL result rows.
// Meter kWh in this project are SAMPLE data; sources carry the kind label ("FILE: sample").
import { createHash } from "node:crypto";

export type SourceKind = "REST: Octopus" | "REST: NESO" | "REST: Elexon" | "REST: Open-Meteo" | "FILE: sample";
export interface EvidenceSource { view: string; kind: SourceKind }
export interface MetricValue { value: number | string | boolean | null; unit: string }
export type Row = Record<string, unknown>;

export interface Evidence {
  id: string;                       // "E1", "E2", ...
  hypothesisId: string;             // "H1".."H10", "DECOMP", "REC"
  title: string;
  sql: string;
  zetarisRunId: string;
  rowCount: number;                 // full result size
  resultSha256: string;             // sha256 of canonicalJson(all rows)
  sampleRows: Row[];                // first <= 10 rows
  metrics: Record<string, MetricValue>;
  sources: EvidenceSource[];
}

export const MAX_SAMPLE_ROWS = 10;

/** JSON with object keys sorted at every level; undefined members are dropped, non-finite numbers become null. */
export function canonicalJson(v: unknown): string {
  if (v === null || v === undefined) return "null";
  if (typeof v === "number") return Number.isFinite(v) ? JSON.stringify(v) : "null";
  if (typeof v === "string" || typeof v === "boolean") return JSON.stringify(v);
  if (typeof v === "bigint") return JSON.stringify(v.toString());
  if (Array.isArray(v)) return "[" + v.map((x) => canonicalJson(x)).join(",") + "]";
  if (typeof v === "object") {
    const o = v as Record<string, unknown>;
    return "{" + Object.keys(o).filter((k) => o[k] !== undefined).sort().map((k) => JSON.stringify(k) + ":" + canonicalJson(o[k])).join(",") + "}";
  }
  return "null";
}
export const sha256Hex = (s: string): string => createHash("sha256").update(s).digest("hex");
export const hashRows = (rows: Row[]): string => sha256Hex(canonicalJson(rows));

/** Metric values must be JSON-safe: NaN / Infinity become null. */
export function cleanMetrics(m: Record<string, MetricValue>): Record<string, MetricValue> {
  const out: Record<string, MetricValue> = {};
  for (const [k, mv] of Object.entries(m)) out[k] = { value: typeof mv.value === "number" && !Number.isFinite(mv.value) ? null : mv.value, unit: mv.unit };
  return out;
}

export class EvidenceStore {
  private items: Evidence[] = [];
  private byId = new Map<string, Evidence>();
  private counter = 0;

  /** Reserves the next id of this investigation. */
  nextId(): string { return `E${++this.counter}`; }
  /** Called with every record as it is registered (progress events); a listener error never breaks an investigation. */
  onAdd?: (e: Evidence) => void;
  add(e: Evidence): Evidence {
    if (this.byId.has(e.id)) throw new Error(`duplicate evidence id ${e.id}`);
    this.items.push(e); this.byId.set(e.id, e);
    try { this.onAdd?.(e); } catch { /* listeners must not break the store */ }
    return e;
  }
  get(id: string): Evidence | undefined { return this.byId.get(id); }
  list(): Evidence[] { return [...this.items]; }
  get size(): number { return this.items.length; }
  /** Adds (or overwrites) metrics on an existing record; the query provenance stays untouched. */
  addMetrics(id: string, metrics: Record<string, MetricValue>): Evidence {
    const e = this.byId.get(id);
    if (!e) throw new Error(`unknown evidence id ${id}`);
    e.metrics = { ...e.metrics, ...cleanMetrics(metrics) };
    return e;
  }
  toJSON(): Evidence[] { return this.items; }
}

export interface EvidenceInput {
  hypothesisId: string;
  title: string;
  sql: string;

// Facts table (spec section 13, step 5): every number the narrative may use, as F1.. with a pre-formatted display string and the evidence it comes from.
// Built deterministically from the decomposition, the hypothesis metrics held in the evidence store, and the recommendations. The LLM never computes a number.
// Meter kWh in this project are SAMPLE data; prices, carbon and weather are real public data.
import { allocateRounded } from "./decompose.ts";
import { addDays } from "./bands.ts";
import type { EvidenceStore } from "./evidence.ts";
import { displayFor, type FactValue } from "./facts_format.ts";
import type { Decomp, HypothesisResult, Scope } from "./hypotheses/types.ts";
import type { Recommendation, TariffComparison } from "./recommend.ts";
import type { DateWindow } from "./windows.ts";
import { hypothesisFacts } from "./facts_hyp.ts";
import { singleRowNumbers } from "./agent_extra.ts";

export interface Fact {
  id: string;                 // "F1", "F2", ...
  key: string;                // stable machine key ("delta_bill", "L", "v_weather"), used by the template narrative
  label: string;
  value: FactValue;           // number in the unit of `unit` (percent as 54.91, pounds as 339.91), or text / date string
  unit: string;               // GBP | % | kWh | p/kWh | kgCO2e | pp | sd | HDD | date | text | ...
  display: string;            // the string the narrative must copy: £339.91, 54.9%, 8,312 kWh, 21.4 p/kWh, 103.0 kgCO2e, 2026-10-17
  evidence: string;           // E# the value comes from
  hypothesis?: string;        // H1..H11 when the fact belongs to one hypothesis; REC for the recommendation; absent for neutral facts
}

export interface FactsInput {
  scope: Scope;
  siteNames: Record<string, string>;
  windowA: DateWindow; windowB: DateWindow;
  decomposition: Decomp;
  results: HypothesisResult[];
  evidence: EvidenceStore;
  rec: Recommendation | null;
  tariff: TariffComparison | null;
  extras?: { purpose: string; evidence: string; rows: number }[];   // planner-proposed SQL that ran: row count, and the numbers of a single-row result
}

const roundTo = (x: number, dp: number): number => Math.round(x * 10 ** dp) / 10 ** dp;

/** Append-only fact list with sequential ids; null / non-finite values are skipped so a missing metric simply yields no fact. */
export class FactTable {
  readonly facts: Fact[] = [];
  add(key: string, label: string, value: FactValue | undefined, unit: string, evidence: string | null | undefined, hypothesis?: string): Fact | null {
    if (value === null || value === undefined || !evidence) return null;
    if (typeof value === "number" && !Number.isFinite(value)) return null;
    const v = typeof value === "number" ? roundTo(value, 4) : value;
    const fact: Fact = { id: `F${this.facts.length + 1}`, key, label, value: v, unit, display: displayFor(v, unit), evidence, ...(hypothesis ? { hypothesis } : {}) };
    this.facts.push(fact);
    return fact;
  }
  get(key: string): Fact | undefined { return this.facts.find((f) => f.key === key); }
}

const pct = (part: number, whole: number): number | null => (whole === 0 ? null : (part / whole) * 100);

function decompositionFacts(t: FactTable, i: FactsInput): void {
  const r = i.decomposition.result;
  if (!r) return;
  const e = i.decomposition.evidenceId;
  const names = i.scope.sites.map((s) => (i.siteNames[s] ? `${s} (${i.siteNames[s]})` : s)).join(", ");
  // V, L, T, S are rounded to whole pence so that V + L + T + S = the bill change exactly as displayed (largest-remainder rounding).

// Narrative verifier (spec section 13, step 7). Pure: no I/O, no clock. It checks a drafted answer against the facts table and the hypothesis statuses:
//  - every number token in a sentence (currency, %, kWh, p/kWh, kg / kgCO2e, pp, dates in ISO or "17 Oct 2026" form, times, plain numbers >= 10 or with decimals)
//    must match a fact CITED IN THAT SENTENCE, by its display string or by its value within the rounding of the token as written;
//  - every sentence cites at least one existing F# and one existing E#;
//  - a hypothesis presented as a cause must be supported; every ruledOut item must be a ruled_out hypothesis.
// Unsigned tokens are compared by magnitude ("fell by £12.34" matches −£12.34); an explicit sign must agree with the fact.
import type { Fact } from "./facts.ts";
import { kindOfUnit, type TokenKind } from "./facts_format.ts";

export type TokenType = TokenKind | "date" | "time" | "abbrev";
export interface Token {
  type: TokenType; raw: string;
  value: number; decimals: number;            // numeric tokens: parsed value and number of decimals as written
  sign: -1 | 0 | 1;                           // explicit sign as written (0: none)
  date?: { y: number | null; m: number; d: number };
  minutes?: number;                           // time of day
}

const MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
const MON = "(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|June?|July?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)";
const NUM = "(?:\\d{1,3}(?:,\\d{3})+|\\d+)(?:\\.\\d+)?";
const SIGN = "[+\\u2212\\u2013-]";
const TOKEN_RE = new RegExp([
  "(?<iso>\\b(\\d{4})-(\\d{2})-(\\d{2})\\b)",
  `(?<dmy>\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+${MON}\\b\\.?(?:,?\\s+(\\d{4})\\b)?)`,
  `(?<mdy>\\b${MON}\\b\\.?\\s+(\\d{1,2})(?:st|nd|rd|th)?\\b(?:,?\\s+(\\d{4})\\b)?)`,
  "(?<time>\\b(\\d{1,2}):(\\d{2})\\b)",
  `(?<money>(?<![\\w.,])(${SIGN})?\\s?£\\s?(${SIGN})?(${NUM})(\\s?(?:[kKmM]|bn)\\b)?)`,
  `(?<unit>(?<![\\w.,])(${SIGN})?(${NUM})\\s?(%|per ?cent(?![a-z])|percent(?![a-z])|percentage points?(?![a-z])|pp(?![a-z])|kg(?:\\s?CO[2\\u2082]e?)?(?![A-Za-z])|kWh(?![A-Za-z])|p/kWh|p per kWh|pence per kWh|pence/kWh|pence(?![a-z])|p(?![\\w/])))`,
  `(?<plain>(?<![\\w.,])(${SIGN})?(${NUM})(?!\\d))`,
].join("|"), "g");

const signOf = (s: string | undefined): -1 | 0 | 1 => (!s ? 0 : s === "+" ? 1 : -1);
const parseNum = (s: string): { value: number; decimals: number } => ({ value: Number(s.replace(/,/g, "")), decimals: s.includes(".") ? s.length - s.indexOf(".") - 1 : 0 });
const monthIndex = (m: string): number => MONTHS.indexOf(m.slice(0, 3).toLowerCase()) + 1;

/** Identifiers that look like numbers but are not: [E3], F12, H10, S2. Blanked out (same length) before tokenising. */
const ID_RE = /\[?\b[EFHS]\d+\b\]?/g;

export function tokenize(text: string): Token[] {
  const clean = text.replace(ID_RE, (m) => " ".repeat(m.length));
  const out: Token[] = [];
  for (const m of clean.matchAll(TOKEN_RE)) {
    const g = m.groups ?? {};
    const raw = m[0];
    if (g.iso) {
      const [, y, mo, d] = g.iso.match(/(\d{4})-(\d{2})-(\d{2})/)!;
      out.push({ type: "date", raw, value: 0, decimals: 0, sign: 0, date: { y: Number(y), m: Number(mo), d: Number(d) } });
    } else if (g.dmy || g.mdy) {
      const s = (g.dmy ?? g.mdy)!;
      const mm = g.dmy ? s.match(new RegExp(`^(\\d{1,2})(?:st|nd|rd|th)?\\s+${MON}\\b\\.?(?:,?\\s+(\\d{4}))?`)) : s.match(new RegExp(`^${MON}\\b\\.?\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,?\\s+(\\d{4}))?`));
      if (!mm) continue;
      const day = Number(g.dmy ? mm[1] : mm[2]), mon = monthIndex(g.dmy ? mm[2] : mm[1]);
      if (day < 1 || day > 31) continue;
      out.push({ type: "date", raw, value: 0, decimals: 0, sign: 0, date: { y: mm[3] ? Number(mm[3]) : null, m: mon, d: day } });
    } else if (g.time) {
      const [, h, mi] = g.time.match(/(\d{1,2}):(\d{2})/)!;
      out.push({ type: "time", raw, value: 0, decimals: 0, sign: 0, minutes: Number(h) * 60 + Number(mi) });
    } else if (g.money) {
      const mm = g.money.match(new RegExp(`^(${SIGN})?\\s?£\\s?(${SIGN})?(${NUM})(\\s?(?:[kKmM]|bn)\\b)?$`))!;
      const n = parseNum(mm[3]);
      out.push({ type: mm[4] ? "abbrev" : "money", raw, ...n, sign: signOf(mm[1] ?? mm[2]) });
    } else if (g.unit) {
      const mm = g.unit.match(new RegExp(`^(${SIGN})?(${NUM})\\s?(.+)$`))!;
      const u = mm[3], n = parseNum(mm[2]);
      const after = clean.slice((m.index ?? 0) + raw.length);
      let type: TokenType;
      if (u === "%" || /^(per ?cent|percent)$/.test(u)) type = "pct";
      else if (/^(pp|percentage points?)$/.test(u)) type = "pp";
      else if (/^kg/.test(u)) type = "kg";
      else if (u === "kWh") type = /^\s*(\/|per\b)/.test(after) ? "plain" : "kwh"; // "11.3 kWh per heating degree day" is a rate, not an amount
      else type = "pkwh";
      out.push({ type, raw, ...n, sign: signOf(mm[1]) });
    } else if (g.plain) {
      const mm = g.plain.match(new RegExp(`^(${SIGN})?(${NUM})$`))!;
      const n = parseNum(mm[2]);
      const after = clean.slice((m.index ?? 0) + raw.length);
      if (/^(st|nd|rd|th)\b/.test(after)) continue;                       // ordinal: "the 5th"
      if (/^[kKmM]\b/.test(after)) { out.push({ type: "abbrev", raw: raw + after[0], ...n, sign: signOf(mm[1]) }); continue; }
      if (n.decimals === 0 && !mm[1] && !mm[2].includes(",") && n.value >= 1990 && n.value <= 2100) continue; // a bare year

// Recommendation (Q4): counterfactual load shift, re-priced on the REAL window-B Agile prices and carbon intensities.
// Per site and local day: flexible load = peak-band (16:00-19:00 local) kWh above the site's night-band median per slot, capped at maxKwhPerDay.
// It is moved, spread evenly, into the cheapest contiguous block of the same local day that does not overlap the peak band; days where that does not save money are left alone.
// Only complete local days (48 slots) are used. Meter kWh are SAMPLE data; prices and carbon are real.
import { sum } from "./decompose.ts";
import { bandOf, localDate } from "./bands.ts";
import { mean } from "./stats.ts";
import type { SlotRow } from "./data.ts";
import { THRESHOLDS as T } from "./hypotheses/thresholds.ts";
import { loadSlots } from "./hypotheses/context.ts";
import { FLAT_TARIFF } from "./flat_tariff.ts";
import type { HypCtx } from "./hypotheses/types.ts";
import { fetchMeta, gbp, metricMap, round } from "./hypotheses/util.ts";

export interface ShiftOptions { maxKwhPerDay?: number; blockSlots?: number }
export interface SiteShift {
  site: string; baselineKwhPerSlot: number | null;
  daysUsed: number; daysShifted: number; shiftedKwh: number;
  costBeforePence: number; costAfterPence: number; savedPence: number;
  savedKgCo2e: number | null;               // null when a carbon intensity is missing in the slots involved
  targetBlock: string | null;               // most common target block, local time "HH:MM-HH:MM"
}
export interface Recommendation {
  scope: string; ok: boolean; reason?: string;
  maxKwhPerDay: number; blockSlots: number;
  sites: SiteShift[];
  total: { daysUsed: number; daysShifted: number; shiftedKwh: number; costBeforeGbp: number; costAfterGbp: number; savedGbp: number; savedKgCo2e: number | null };
  text: string;
  evidence: string[];
}

const median = (xs: number[]): number => { const s = [...xs].sort((a, b) => a - b), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const hhmm = (h: number): string => `${String(Math.floor(h)).padStart(2, "0")}:${h % 1 ? "30" : "00"}`;

/** Counterfactual for ONE site from its window-B slots (sorted or not). Pure. */
export function planShift(rowsIn: SlotRow[], opts: ShiftOptions = {}): SiteShift {
  const cap = opts.maxKwhPerDay ?? T.REC_MAX_KWH_PER_DAY, n = opts.blockSlots ?? T.REC_BLOCK_SLOTS;
  const rows = [...rowsIn].sort((a, b) => a.ts.localeCompare(b.ts));
  const site = rows[0]?.site ?? "";
  const nights = rows.filter((r) => bandOf(r.ts) === "night").map((r) => r.kwh);
  const base = nights.length ? median(nights) : null;
  const out: SiteShift = { site, baselineKwhPerSlot: base, daysUsed: 0, daysShifted: 0, shiftedKwh: 0, costBeforePence: 0, costAfterPence: 0, savedPence: 0, savedKgCo2e: 0, targetBlock: null };
  if (base === null) return out;
  const byDay = new Map<string, SlotRow[]>();
  for (const r of rows) (byDay.get(localDate(r.ts)) ?? byDay.set(localDate(r.ts), []).get(localDate(r.ts))!).push(r);
  const kgParts: number[] = [];
  const blockStarts = new Map<number, number>();
  for (const [, day] of [...byDay].sort((a, b) => a[0].localeCompare(b[0]))) {
    if (day.length !== T.SLOTS_PER_DAY) continue;
    out.daysUsed++;
    const dayCost = sum(day.map((r) => r.kwh * r.p));
    out.costBeforePence += dayCost;
    const peak = day.map((r, k) => ({ r, k })).filter((x) => bandOf(x.r.ts) === "peak");
    const flex = peak.map((x) => Math.max(0, x.r.kwh - base));
    const F = sum(flex);
    const moved = Math.min(F, cap);
    let after = dayCost;
    if (moved > 1e-9) {
      const f = moved / F;
      // cheapest contiguous block of n slots that does not touch the peak band
      let best = -1, bestMean = Infinity;
      for (let s = 0; s + n <= day.length; s++) {
        const blk = day.slice(s, s + n);
        if (blk.some((r) => bandOf(r.ts) === "peak")) continue;
        const m = mean(blk.map((r) => r.p));
        if (m < bestMean - 1e-12) { bestMean = m; best = s; }
      }
      if (best >= 0) {
        const blk = day.slice(best, best + n);
        const removed = sum(peak.map((x, i) => flex[i] * f * x.r.p));
        const added = (moved / n) * sum(blk.map((r) => r.p));
        if (removed - added > 1e-9) {
          after = dayCost - removed + added;
          out.daysShifted++; out.shiftedKwh += moved;
          blockStarts.set(best, (blockStarts.get(best) ?? 0) + 1);
          const ci = [...peak.map((x) => x.r.intensity), ...blk.map((r) => r.intensity)];
          if (ci.some((v) => v === null)) kgParts.push(NaN);
          else kgParts.push((sum(peak.map((x, i) => flex[i] * f * (x.r.intensity as number))) - (moved / n) * sum(blk.map((r) => r.intensity as number))) / 1000);
        }
      }

