  label: string | null;
  kind: string | null;
  tier: string | null;
  latencyMs: number;
  receiptId: string | null;
  raceWidth: number | null;
  usage: Usage;
  fallbackReason?: string;
  fromCache?: boolean;
}

export interface LlmCall {
  step: string;
  route?: Route;
  error?: string;
  wallMs?: number;
  rejected?: string;
}

export interface Verification {
  passed: boolean;
