                <span className="meta-label">Rows</span>
                <span>{evidence.rowCount}</span>
              </div>
              <div>
                <span className="meta-label">sha256</span>
                <code title={evidence.resultSha256}>{shortSha(evidence.resultSha256, 12)}</code>
              </div>
