:root,
[data-theme="light"] {
  --bg: #f4f1ea;
  --bg-elev: #fffcf6;
  --bg-soft: #ebe6dc;
  --ink: #1c1914;
  --ink-muted: #5c564c;
  --accent: #0f5c4c;
  --accent-soft: #d8ebe4;
  --warn: #8a4b12;
  --danger: #8b2e2e;
  --border: #d5cfc3;
  --chip: #e8e2d6;
  --shadow: 0 1px 0 rgba(28, 25, 20, 0.06), 0 12px 32px rgba(28, 25, 20, 0.06);
  --wf-total: #1c1914;
  --wf-up: #b45309;
  --wf-down: #0f5c4c;
  --wf-zero: #9a9286;
  --drawer-w: min(440px, 100vw);
  --font-display: "Fraunces", "Georgia", serif;
  --font-body: "Source Sans 3", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  color-scheme: light;
}

[data-theme="dark"] {
  --bg: #161410;
  --bg-elev: #1f1b16;
  --bg-soft: #2a251f;
  --ink: #f3efe6;
  --ink-muted: #b0a89a;
  --accent: #6fbfa8;
  --accent-soft: #243832;
  --warn: #e0a05a;
  --danger: #e08a8a;
  --border: #3a342c;
  --chip: #2e2922;
  --shadow: 0 1px 0 rgba(0, 0, 0, 0.35), 0 16px 40px rgba(0, 0, 0, 0.35);
  --wf-total: #f3efe6;
  --wf-up: #e0a05a;
  --wf-down: #6fbfa8;
  --wf-zero: #6b6358;
  color-scheme: dark;
}

*,
*::before,
*::after {
