+  background: var(--bg);
+  border-radius: 8px;
+  overflow: auto;
+  max-height: 12rem;
+  font-size: 0.8rem;
+}
+
+.how-it-works {
+  margin-top: 2rem;
+  padding-top: 1.5rem;
+  border-top: 1px solid var(--border);
+}
+
+.pipeline {
+  width: 100%;
+  height: auto;
+  display: block;
+  margin: 0.5rem 0 1rem;
+}
+
+.pipe-box {
+  fill: var(--bg-elev);
+  stroke: var(--border);
+  stroke-width: 1.5;
+}
+
+.pipe-box.accent {
+  fill: var(--accent-soft);
+}
+
+.pipe-title {
+  fill: var(--ink);
+  font-family: var(--font-display);
+  font-size: 14px;
+  font-weight: 650;
+}
+
+.pipe-line {
+  fill: var(--ink-muted);
+  font-family: var(--font-body);
+  font-size: 11px;
+}
+
+.pipe-line.muted {
+  fill: var(--ink-muted);
+  font-size: 10px;
+}
+
+.pipe-arrow {
+  stroke: var(--ink-muted);
+  stroke-width: 1.5;
+}
+
+.built-with {
+  font-size: 0.88rem;
+  color: var(--ink-muted);
+  margin: 0;
+}
+
+/* Evidence drawer */
+.drawer-backdrop {
+  position: fixed;
+  inset: 0;
+  background: rgba(20, 16, 12, 0.35);
+  opacity: 0;
+  pointer-events: none;
+  transition: opacity 0.2s ease;
+  z-index: 40;
+}
+
+.drawer-backdrop.show {
+  opacity: 1;
+  pointer-events: auto;
+}
+
+.evidence-drawer {
+  position: fixed;
+  top: 0;
+  right: 0;
+  width: var(--drawer-w);
+  height: 100vh;
+  background: var(--bg-elev);
+  border-left: 1px solid var(--border);
+  box-shadow: var(--shadow);
+  z-index: 50;
+  transform: translateX(105%);
+  transition: transform 0.25s ease;
+  overflow: auto;
+  padding: 1.1rem 1.15rem 2rem;
+}
+
+.evidence-drawer.open {
+  transform: translateX(0);
+}
+
+.drawer-head {
+  display: flex;
+  justify-content: space-between;
+  gap: 0.75rem;
+  align-items: flex-start;
+}
+
+.drawer-id {
+  margin: 0;
+  font-family: var(--font-mono);
+  font-size: 0.85rem;
+  color: var(--accent);
+  font-weight: 600;
+}
+
+.drawer-head h2 {
+  margin: 0.15rem 0 0;
+  font-family: var(--font-display);
+  font-size: 1.2rem;
+}
+
+.icon-btn {
+  font-size: 1.4rem;
+  line-height: 1;
+  width: 2.2rem;
+  height: 2.2rem;
+  padding: 0;
+  flex-shrink: 0;
+}
+
+.drawer-badges {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 0.35rem;
+  margin: 0.85rem 0;
+}
+
+.drawer-meta {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 0.65rem;
+  margin-bottom: 1rem;
+  font-size: 0.88rem;
+}
+
+.meta-label {
+  display: block;
+  font-size: 0.72rem;
+  text-transform: uppercase;
+  letter-spacing: 0.04em;
+  color: var(--ink-muted);
+  margin-bottom: 0.15rem;
+}
+
+.sql-block {
+  margin-bottom: 1rem;
+}
+
+.sql-head {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  margin-bottom: 0.35rem;
+  font-size: 0.85rem;
+  color: var(--ink-muted);
+}
+
+.sql-block pre {
+  margin: 0;
+  padding: 0.75rem;
+  background: var(--bg);
+  border: 1px solid var(--border);
+  border-radius: 8px;
+  overflow: auto;
+  max-height: 14rem;
+  white-space: pre-wrap;
+  word-break: break-word;
+  font-size: 0.78rem;
+  line-height: 1.45;
+}
+
+.metrics h3,
+.sample-rows h3 {
+  font-size: 0.9rem;
+  margin: 0 0 0.45rem;
+}
+
+.metrics dl {
+  margin: 0 0 1rem;
+  display: grid;
+  gap: 0.25rem;
+}
+
+.metric-row {
+  display: grid;
+  grid-template-columns: 1fr auto;
+  gap: 0.5rem;
+  font-size: 0.85rem;
+  padding: 0.25rem 0;
+  border-bottom: 1px solid var(--border);
+}
+
+.metric-row dt {
+  color: var(--ink-muted);
+  font-family: var(--font-mono);
+  font-size: 0.78rem;
+}
+
+.table-scroll {
+  overflow: auto;
+  max-height: 16rem;
+  border: 1px solid var(--border);
+  border-radius: 8px;
+}
+
+.sample-rows table {
+  border-collapse: collapse;
+  font-size: 0.72rem;
+  font-family: var(--font-mono);
+  width: max-content;
+  min-width: 100%;
+}
+
+.sample-rows th,
+.sample-rows td {
+  padding: 0.35rem 0.5rem;
+  border-bottom: 1px solid var(--border);
+  text-align: left;
+  white-space: nowrap;
+}
+
+.sample-rows th {
+  position: sticky;
+  top: 0;
+  background: var(--bg-soft);
+  color: var(--ink-muted);
+}
+
+@media (max-width: 560px) {
+  .app {
+    padding: 0.85rem 0.75rem 2.5rem;
+  }
+
+  .top-bar {
+    flex-direction: column;
+  }
+
+  .theme-toggle {
+    align-self: flex-end;
+  }
+
+  .drawer-meta {
+    grid-template-columns: 1fr;
+  }
+
+  .pipeline {
+    min-height: 140px;
+  }
+
+  .wf-label {
+    font-size: 9px;
+  }
+}
+
+@media (max-width: 400px) {
+  html {
+    font-size: 16px;
+  }
+
+  .wordmark {
+    font-size: 1.85rem;
+  }
+
+  .question-box,
+  .timeline,
+  .answer-card,
+  .ruled-out,
+  .rec-card,
+  .memory-panel {
+    padding: 0.9rem;
+  }
+}

success.afterFullFileContent:
:root,
[data-theme="light"] {
  --bg: #f4f1ea;
  --bg-elev: #fffcf6;
  --bg-soft: #ebe6dc;
  --ink: #1c1914;
  --ink-muted: #5c564c;
  --accent: #0f5c4c;
  --accent-soft: #d8ebe4;
  --warn: #8a4b12;
  --danger: #8b2e2e;
  --border: #d5cfc3;
  --chip: #e8e2d6;
  --shadow: 0 1px 0 rgba(28, 25, 20, 0.06), 0 12px 32px rgba(28, 25, 20, 0.06);
  --wf-total: #1c1914;
  --wf-up: #b45309;
  --wf-down: #0f5c4c;
  --wf-zero: #9a9286;
  --drawer-w: min(440px, 100vw);
  --font-display: "Fraunces", "Georgia", serif;
  --font-body: "Source Sans 3", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  color-scheme: light;
}

[data-theme="dark"] {
  --bg: #161410;
  --bg-elev: #1f1b16;
  --bg-soft: #2a251f;
  --ink: #f3efe6;
  --ink-muted: #b0a89a;
  --accent: #6fbfa8;
  --accent-soft: #243832;
  --warn: #e0a05a;
  --danger: #e08a8a;
  --border: #3a342c;
  --chip: #2e2922;
  --shadow: 0 1px 0 rgba(0, 0, 0, 0.35), 0 16px 40px rgba(0, 0, 0, 0.35);
  --wf-total: #f3efe6;
  --wf-up: #e0a05a;
  --wf-down: #6fbfa8;
  --wf-zero: #6b6358;
  color-scheme: dark;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-size: 17px;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--font-body);
  background:
    radial-gradient(ellipse 80% 50% at 10% -10%, color-mix(in srgb, var(--accent) 12%, transparent), transparent),
    radial-gradient(ellipse 60% 40% at 100% 0%, color-mix(in srgb, var(--warn) 8%, transparent), transparent),
    var(--bg);
  color: var(--ink);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

button,
textarea,
select,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

code,
pre {
  font-family: var(--font-mono);
  font-size: 0.85em;
}

.app {
  max-width: 920px;
  margin: 0 auto;
  padding: 1.25rem 1.1rem 3rem;
}

.top-bar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.theme-toggle {
  flex-shrink: 0;
  border: 1px solid var(--border);
  background: var(--bg-elev);
  border-radius: 999px;
  padding: 0.35rem 0.85rem;
  font-size: 0.85rem;
  color: var(--ink-muted);
}

.site-header {
  flex: 1;
  min-width: 0;
}

.wordmark {
  font-family: var(--font-display);
  font-weight: 650;
  font-size: clamp(2rem, 5vw, 2.6rem);
  letter-spacing: -0.02em;
  margin: 0 0 0.35rem;
  line-height: 1.1;
}

.tagline {
  margin: 0 0 0.9rem;
  color: var(--ink-muted);
  max-width: 36rem;
  font-size: 1.02rem;
}

.status-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.28rem 0.7rem;
  border-radius: 999px;
  background: var(--chip);
  font-size: 0.78rem;
  font-weight: 500;
  border: 1px solid transparent;
}

.chip.ok {
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
  background: var(--accent-soft);
}

.chip.warn {
  border-color: color-mix(in srgb, var(--warn) 40%, var(--border));
}

.offline-notice {
  margin: 0 0 1rem;
  padding: 0.55rem 0.85rem;
  border-radius: 8px;
  background: color-mix(in srgb, var(--warn) 14%, var(--bg-elev));
  border: 1px solid color-mix(in srgb, var(--warn) 35%, var(--border));
  color: var(--warn);
  font-size: 0.9rem;
}

.main {
  display: flex;
  flex-direction: column;
  gap: 1.35rem;
}

.question-box,
.timeline,
.answer-card,
.ruled-out,
.rec-card,
.clarify,
.memory-panel {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.1rem 1.2rem 1.25rem;
  box-shadow: var(--shadow);
}

.question-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.5rem;
}

.question-head label {
  font-weight: 600;
}

.sample-badge {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 0.2rem 0.55rem;
  border-radius: 4px;
  background: var(--bg-soft);
  border: 1px dashed var(--border);
  color: var(--ink-muted);
}

.question-box textarea {
  width: 100%;
  resize: vertical;
  min-height: 4.5rem;
  padding: 0.75rem 0.85rem;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--bg);
  outline: none;
}

.question-box textarea:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 22%, transparent);
}

.question-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: flex-end;
  margin-top: 0.75rem;
}

.site-select {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.85rem;
  color: var(--ink-muted);
  flex: 1;
  min-width: 160px;
}

.site-select select {
  padding: 0.55rem 0.7rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
}

.ask-btn {
  border: none;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  padding: 0.65rem 1.25rem;
  border-radius: 999px;
  min-height: 2.6rem;
}

[data-theme="dark"] .ask-btn {
  color: #10241c;
}

.ask-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.suggestions {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin-top: 0.9rem;
}

.suggestion {
  text-align: left;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.55rem 0.75rem;
  color: var(--ink-muted);
  font-size: 0.92rem;
}

.suggestion:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--ink);
}

.timeline h2,
.answer-card h2,
.ruled-out h2,
.rec-card h2,
.how-it-works h2,
.clarify h2 {
  font-family: var(--font-display);
  font-weight: 650;
  font-size: 1.35rem;
  margin: 0 0 0.75rem;
}

.timeline-stages {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.45rem;
}

.stage {
  display: grid;
  grid-template-columns: 14px 1fr auto;
  gap: 0.55rem;
  align-items: center;
  color: var(--ink-muted);
  font-size: 0.95rem;
}

.stage-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
}

.stage.active .stage-dot {
  background: var(--accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 25%, transparent);
}

.stage.done {
  color: var(--ink);
}

.stage.done .stage-dot {
  background: var(--accent);
}

.stage-ms {
  font-family: var(--font-mono);
  font-size: 0.78rem;
}

.llm-routes {
  list-style: none;
  margin: 1rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.4rem;
}

.llm-routes li {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 0.85rem;
  padding: 0.5rem 0.65rem;
  background: var(--bg-soft);
  border-radius: 8px;
  font-size: 0.88rem;
}

.llm-routes li.fallback {
