  font-size: 0.9rem;
  color: var(--ink-muted);
  font-weight: 600;
}

.evidence-stream ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.4rem;
}

.evidence-pill {
  width: 100%;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35rem 0.65rem;
  text-align: left;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.55rem 0.7rem;
}

.ev-title {
  flex: 1;
  min-width: 10rem;
}

.ev-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.src-badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 0.15rem 0.45rem;
  border-radius: 4px;
  background: var(--chip);
  color: var(--ink-muted);
  white-space: nowrap;
}

.src-badge.muted {
