}

.timeline-done,
.timeline-reset {
  margin: 0.85rem 0 0;
  font-size: 0.9rem;
  color: var(--ink-muted);
}

.answer-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.5rem;
}

.answer-head h2 {
  margin: 0;
  flex: 1;
  min-width: 12rem;
}

.verify-badge {
