  stroke-dasharray: 3 3;
  stroke-width: 1;
}

.answer-body {
  display: grid;
  gap: 0.75rem;
}

.sentence {
  margin: 0;
}

.cite {
  display: inline-flex;
  align-items: center;
  margin: 0 0.15rem;
  padding: 0.05rem 0.4rem;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 0.78em;
  font-weight: 500;
  border: 1px solid var(--border);
