  text-align: left;
  background: transparent;
  border: none;
  font-weight: 600;
  padding: 0;
  color: var(--ink);
}

.memory-body {
  margin-top: 0.85rem;
  display: grid;
  gap: 0.85rem;
}

.memory-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.65rem;
}

.memory-list li {
  padding: 0.65rem 0.75rem;
  border-radius: 8px;
  background: var(--bg);
  border: 1px solid var(--border);
}

.memory-list li.focus {
  border-color: var(--accent);
}

.note-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 0.85rem;
  font-size: 0.78rem;
  color: var(--ink-muted);
  margin-bottom: 0.35rem;
}

.note-form {
  display: grid;
  gap: 0.4rem;
}

.note-form textarea {
  width: 100%;
  padding: 0.6rem 0.7rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
  resize: vertical;
}

.note-form button,
.text-btn,
.icon-btn {
  border: 1px solid var(--border);
  background: var(--bg-soft);
  border-radius: 8px;
  padding: 0.45rem 0.8rem;
}

.text-btn {
  background: transparent;
  border: none;
  padding: 0;
  color: var(--accent);
  font-size: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.audit-pre {
  margin: 0;
  padding: 0.75rem;
  background: var(--bg);
  border-radius: 8px;
  overflow: auto;
  max-height: 12rem;
  font-size: 0.8rem;
}

.how-it-works {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
}

.pipeline {
  width: 100%;
  height: auto;
  display: block;
  margin: 0.5rem 0 1rem;
}

.pipe-box {
  fill: var(--bg-elev);
  stroke: var(--border);
  stroke-width: 1.5;
}

.pipe-box.accent {
  fill: var(--accent-soft);
}

.pipe-title {
  fill: var(--ink);
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 650;
}

.pipe-line {
  fill: var(--ink-muted);
  font-family: var(--font-body);
  font-size: 11px;
}

.pipe-line.muted {
  fill: var(--ink-muted);
  font-size: 10px;
}

.pipe-arrow {
  stroke: var(--ink-muted);
  stroke-width: 1.5;
}

.built-with {
  font-size: 0.88rem;
  color: var(--ink-muted);
  margin: 0;
}

/* Evidence drawer */
.drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(20, 16, 12, 0.35);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
  z-index: 40;
}

.drawer-backdrop.show {
  opacity: 1;
  pointer-events: auto;
}

.evidence-drawer {
  position: fixed;
  top: 0;
  right: 0;
  width: var(--drawer-w);
  height: 100vh;
  background: var(--bg-elev);
  border-left: 1px solid var(--border);
  box-shadow: var(--shadow);
  z-index: 50;
  transform: translateX(105%);
  transition: transform 0.25s ease;
  overflow: auto;
  padding: 1.1rem 1.15rem 2rem;
}

.evidence-drawer.open {
  transform: translateX(0);
}

.drawer-head {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: flex-start;
}

.drawer-id {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--accent);
  font-weight: 600;
}

.drawer-head h2 {
  margin: 0.15rem 0 0;
  font-family: var(--font-display);
  font-size: 1.2rem;
}

.icon-btn {
  font-size: 1.4rem;
  line-height: 1;
  width: 2.2rem;
  height: 2.2rem;
  padding: 0;
  flex-shrink: 0;
}

.drawer-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin: 0.85rem 0;
}

.drawer-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
  margin-bottom: 1rem;
  font-size: 0.88rem;
}

.meta-label {
  display: block;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--ink-muted);
  margin-bottom: 0.15rem;
}

.sql-block {
  margin-bottom: 1rem;
}

.sql-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.35rem;
  font-size: 0.85rem;
  color: var(--ink-muted);
}

.sql-block pre {
  margin: 0;
  padding: 0.75rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: auto;
  max-height: 14rem;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 0.78rem;
  line-height: 1.45;
}

.metrics h3,
.sample-rows h3 {
  font-size: 0.9rem;
  margin: 0 0 0.45rem;
}

.metrics dl {
  margin: 0 0 1rem;
  display: grid;
  gap: 0.25rem;
}

.metric-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.5rem;
  font-size: 0.85rem;
  padding: 0.25rem 0;
  border-bottom: 1px solid var(--border);
}

.metric-row dt {
  color: var(--ink-muted);
  font-family: var(--font-mono);
  font-size: 0.78rem;
}

.table-scroll {
  overflow: auto;
  max-height: 16rem;
  border: 1px solid var(--border);
  border-radius: 8px;
}

.sample-rows table {
  border-collapse: collapse;
  font-size: 0.72rem;
  font-family: var(--font-mono);
  width: max-content;
  min-width: 100%;
}

.sample-rows th,
.sample-rows td {
  padding: 0.35rem 0.5rem;
  border-bottom: 1px solid var(--border);
  text-align: left;
  white-space: nowrap;
}

.sample-rows th {
  position: sticky;
  top: 0;
  background: var(--bg-soft);
  color: var(--ink-muted);
}

@media (max-width: 560px) {
  .app {
    padding: 0.85rem 0.75rem 2.5rem;
  }

  .top-bar {
    flex-direction: column;
  }

  .theme-toggle {
    align-self: flex-end;
  }

  .drawer-meta {
    grid-template-columns: 1fr;
  }

  .pipeline {
    min-height: 140px;
  }

  .wf-label {
    font-size: 9px;
  }
}

@media (max-width: 400px) {
  html {
    font-size: 16px;
  }

  .wordmark {
    font-size: 1.85rem;
  }

  .question-box,
  .timeline,
  .answer-card,
  .ruled-out,
  .rec-card,
  .memory-panel {
    padding: 0.9rem;
  }
}

